<?php

namespace App\Support;

use Illuminate\Support\Facades\Storage;

/**
 * Builds public URLs for files uploaded through Filament.
 *
 * All uploads (post covers, post content images, profile avatars and project
 * thumbnails) are stored on the "public" disk. The URL is generated by the
 * disk itself, so it follows APP_URL (e.g. https://api.asepblog.online in
 * production) and nothing is hardcoded here.
 */
class Media
{
    /**
     * Resolve a stored file path to an absolute, publicly reachable URL.
     */
    public static function url(?string $path): ?string
    {
        if ($path === null || trim($path) === '') {
            return null;
        }

        // Already an absolute URL (e.g. an externally hosted image).
        if (preg_match('#^https?://#i', $path) === 1) {
            return $path;
        }

        $disk = Storage::disk('public');

        // Do not expose a URL for a file that is missing from the configured
        // public disk. This also works with remote disks such as S3.
        if (! $disk->exists($path)) {
            return null;
        }

        return $disk->url($path);
    }
}
